import{_ as t,o as e,c as n,ag as r}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"科学日报 · 2026-10-12（古人类学 / 群体遗传）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/paleoanthropology/science-daily-2026-10-12.md","filePath":"topics/paleoanthropology/science-daily-2026-10-12.md"}'),s={name:"topics/paleoanthropology/science-daily-2026-10-12.md"};function c(a,o,i,l,d,g){return e(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="科学日报-·-2026-10-12-古人类学-群体遗传" tabindex="-1">科学日报 · 2026-10-12（古人类学 / 群体遗传） <a class="header-anchor" href="#科学日报-·-2026-10-12-古人类学-群体遗传" aria-label="Permalink to &quot;科学日报 · 2026-10-12（古人类学 / 群体遗传）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-12.md</code> — 第35期</p></blockquote><hr><h2 id="一条基因为波利尼西亚人的-层层奠基者效应-作证-science" tabindex="-1">一条基因为波利尼西亚人的&quot;层层奠基者效应&quot;作证（Science） <a class="header-anchor" href="#一条基因为波利尼西亚人的-层层奠基者效应-作证-science" aria-label="Permalink to &quot;一条基因为波利尼西亚人的&quot;层层奠基者效应&quot;作证（Science）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-12.md</code> ｜ DOI: 10.1126/science.aec7662</p></blockquote><ul><li>背景：<strong>奠基者效应（founder effect）<strong>会造成强烈的</strong>群体特异等位基因频率分化</strong>，并带来<strong>隐性遗传病</strong>——欧洲的<strong>芬兰人、阿米什人群</strong>都有据此设计的<strong>临床遗传检测</strong>。</li><li>方法：覆盖波利尼西亚的<strong>全基因组序列</strong>，量化定居过程中的<strong>累积瓶颈</strong>。</li><li>关键发现：波利尼西亚人向东定居时经历了比欧洲群体<strong>强一个数量级</strong>的累积奠基者效应；<strong>瓶颈最严重</strong>的两群体是<strong>夏威夷</strong>与<strong>复活节岛（Rapa Nui）</strong>。</li><li>迁徙推论：这两个<strong>地理遥远却遗传最接近</strong>的岛屿，很可能由<strong>同一批&quot;远航者&quot;<strong>定居，其祖源可上溯到 <strong>曼加雷瓦（Mangareva）</strong>——即</strong>层层嵌套（nested）的海洋奠基事件</strong>。</li><li>医学落点：识别出该连锁奠基事件产生的<strong>临床相关变异</strong>，包括<strong>东波利尼西亚常见的 FAN1 功能缺失突变</strong>。</li><li>意义：把<strong>人类学迁徙史</strong>直接接到<strong>遗传病筛查</strong>上——&quot;谁从哪里来&quot;变成&quot;该在哪查哪些致病变异&quot;。</li><li>洞察（对本库 <code>paleoanthropology</code>）：<strong>地理距离 ≠ 遗传距离</strong>。群体史的关键量是<strong>迁移的次序与瓶颈的嵌套</strong>，不是地图上的远近。与 <code>science-daily-2026-09-21.md</code>（东天山青铜古 DNA：草原东扩贡献很小）同源：<strong>&quot;看起来在扩散&quot;与&quot;基因上真留下痕迹&quot;是两回事，必须靠序列而非叙事判断。</strong></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/paleoanthropology/index.md</code> ｜ 第35期 科学板块</p></blockquote><p>关键词：奠基者效应、nested founder effect、波利尼西亚、全基因组测序、东波利尼西亚、夏威夷、复活节岛、Rapa Nui、曼加雷瓦、Mangareva、远航者、FAN1、功能缺失突变、隐性遗传病、群体瓶颈、遗传筛查、地理距离≠遗传距离 关联：<code>topics/paleoanthropology/science-daily-2026-09-21.md</code>（东天山青铜古 DNA，同为&quot;用序列判迁徙&quot;）、<code>topics/paleoanthropology/science-daily-2026-09-15.md</code>（丹尼索瓦人）、<code>topics/biomedicine/science-daily-2026-10-12.md</code>（群体特异变异的临床落点）、<code>topics/paleoanthropology/index.md</code>（古 DNA / 遗传学主线）</p>',9)])])}const q=t(s,[["render",c]]);export{u as __pageData,q as default};
